insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:snayckstx_sinixt', 'Sn̓ʕaýckstx (Sinixt)', 'not_federally_recognized', 'https://sinixt.com', 'Recognition research 2026-11-25', 'https://decisions.scc-csc.ca/scc-csc/news/fr/7122/1/document.do') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:snayckstx_sinixt', 'CA', array['BC']::text[], 'declared_extinct', '{}'::text[], null, null, 'https://sinixt.com', 'Sinixt Confederacy; Arrow Lakes Band (Indian Act name); Lakes Tribe (Colville Confederated Tribes)', 'SCC case summary: reserve set aside for the Arrow Lakes in 1902; in 1956 the federal government declared the Arrow Lakes Band extinct for the purposes of the Indian Act. In Desautel the SCC held that the Lakes Tribe of the Colville Confederated Tribes (US), found to be a successor group of the Sinixt, can hold s.35 Aboriginal rights. Own site describes the nation as a transboundary tribe and an Aboriginal people of Canada. No Arrow Lakes band appears in the ISC First Nation list.', array['https://decisions.scc-csc.ca/scc-csc/news/fr/7122/1/document.do', 'https://scc-csc.ca/judgments-jugements/cb/2021/38734/', 'https://sinixt.com', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:snayckstx_sinixt', 'R v Desautel, 2021 SCC 17', '2021-04-23', 'https://scc-csc.ca/judgments-jugements/cb/2021/38734/', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:nunatukavut_community_council', 'NunatuKavut Community Council', 'not_federally_recognized', 'https://nunatukavut.ca', 'Recognition research 2026-11-25', 'https://www.canada.ca/en/crown-indigenous-relations-northern-affairs/news/2019/09/moving-forward-on-self-determination-mou-between-canada-and-the-nunatukavut-community-council.html') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:nunatukavut_community_council', 'CA', array['NL']::text[], 'no_band_status_seeking', '{}'::text[], null, null, 'https://nunatukavut.ca', 'NunatuKavut Inuit; NCC; Southern Inuit of NunatuKavut', 'Inuit collective (not an Indian Act band context). CIRNAC: MOU signed 2019-09-05 under a Recognition of Indigenous Rights and Self-Determination Discussion Table (launched July 2018); NCC described as governing body for approx. 6,000 NunatuKavut Inuit. Federal Court (2024 FC 896) stated the MOU does not recognize NCC as an Aboriginal people or create s.35 rights.', array['https://www.canada.ca/en/crown-indigenous-relations-northern-affairs/news/2019/09/moving-forward-on-self-determination-mou-between-canada-and-the-nunatukavut-community-council.html', 'https://decisions.fca-caf.ca/fc-cf/decisions/en/525805/1/document.do', 'https://nunatukavut.ca/moving-forward-on-self-determination-mou-between-canada-and-the-nunatukavut-community-council/']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:nunatukavut_community_council', 'Innu Nation Inc. v. Canada (Attorney General), 2024 FC 896', '2024-06-12', 'https://decisions.fca-caf.ca/fc-cf/decisions/en/525805/1/document.do', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:antoine_nation', 'Antoine Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://www.ontario.ca/page/algonquin-land-claim') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:antoine_nation', 'CA', array['ON']::text[], 'non_status_organized', '{}'::text[], null, 'Represented in Algonquins of Ontario (AOO) tripartite land claim negotiations with Ontario and Canada; Agreement-in-Principle signed 2016; Final Agreement under negotiation (no treaty in force)', null, 'Antoine (AOO list)', 'One of ten AOO communities named by Ontario and CIRNAC; not listed as a band in the ISC First Nation open data list (only Algonquins of Pikwakanagan First Nation, band 163, is listed). Name ''Antoine Nation'' as used in FedNor release 2024-05: https://www.canada.ca/en/fednor/news/2024/05/government-of-canada-invests-200000-to-support-the-construction-of-antoine-nations-new-multi-use-facility.html', array['https://www.ontario.ca/page/algonquin-land-claim', 'https://rcaanc-cirnac.gc.ca/eng/1355436558998/1539789262384', 'https://www.tanakiwin.com/?p=117', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
