insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:bonnechere', 'CA', array['ON']::text[], 'non_status_organized', '{}'::text[], null, 'Represented in Algonquins of Ontario (AOO) tripartite land claim negotiations with Ontario and Canada; Agreement-in-Principle signed 2016; Final Agreement under negotiation (no treaty in force)', 'https://bafn.ca', 'Bonnechere Algonquin community (AOO list)', 'One of ten AOO communities named by Ontario and CIRNAC; not listed as a band in the ISC First Nation open data list (only Algonquins of Pikwakanagan First Nation, band 163, is listed). Self-name not verified from own site (site reproduces AOO content); name as listed by AOO/Ontario.', array['https://www.ontario.ca/page/algonquin-land-claim', 'https://rcaanc-cirnac.gc.ca/eng/1355436558998/1539789262384', 'https://www.tanakiwin.com/?p=117', 'https://bafn.ca', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
