insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:ardoch_algonquin_first_nation', 'CA', array['ON']::text[], 'non_status_organized', '{}'::text[], null, null, 'https://aafna.ca', 'AAFN; Kichi Sìbì Anishinàbeg (people); Ardoch Algonquin First Nation and Allies (SCC style of cause)', 'Named in Lovelace v. Ontario (2000 SCC 37, para. 9) among the ''non-band First Nations'' appellants; the SCC stated (para. 16) the appellant groups ''are non-status since they are not registered as Indian Act bands'' (status as of 2000). Not listed in the ISC First Nation list. Separate entity from ''Snimikobi (Ardoch)'' listed in the AOO negotiations.', array['https://decisions.scc-csc.ca/scc-csc/scc-csc/en/1800/1/document.do', 'https://aafna.ca', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
