insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:kawartha_nishnawbe_first_nation', 'CA', array['ON']::text[], 'non_status_organized', '{}'::text[], null, null, null, 'Kawartha Nishnawbe', 'Named in Lovelace v. Ontario (2000 SCC 37, para. 9) among the ''non-band First Nations'' appellants; the SCC stated (para. 16) the appellant groups ''are non-status since they are not registered as Indian Act bands'' (status as of 2000). Parks Canada contribution record (2024-03-27 to 2025-04-30) lists recipient legal name ''Kawartha Nishnawbe First Nation'' for consultation on Burleigh Falls Dam (Trent-Severn Waterway). Not listed in the ISC First Nation list. No own website located.', array['https://decisions.scc-csc.ca/scc-csc/scc-csc/en/1800/1/document.do', 'https://search.open.canada.ca/grants/record/pc%2C154-2023-2024-Q4-00202%2Ccurrent', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
