insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:beaverhouse_first_nation', 'Beaverhouse First Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://decisions.scc-csc.ca/scc-csc/scc-csc/en/1800/1/document.do') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:beaverhouse_first_nation', 'CA', array['ON']::text[], 'other', '{}'::text[], null, null, null, 'Beaver-House First Nation', 'Named in Lovelace v. Ontario (2000 SCC 37, para. 9) among the ''non-band First Nations'' appellants; the SCC stated (para. 16) the appellant groups ''are non-status since they are not registered as Indian Act bands'' (status as of 2000). Canada''s acceptance letter of 2022-04-19 (reported by Nishnawbe Aski Nation 2022-05-24) recognized Beaverhouse as a First Nation collectivity with s.35 rights. ISC briefing notes ''Agreement for the Recognition of Beaverhouse First Nation as a Band under the Indian Act'' (received 2025-03-17, For Decision) and ''Advancing Band Creation Negotiations'' (received 2025-10-27) indicate band status still in process. Not listed in the ISC First Nation list as of retrieval. Borderline: partial federal recognition without band status.', array['https://decisions.scc-csc.ca/scc-csc/scc-csc/en/1800/1/document.do', 'https://search.open.canada.ca/briefingt/record/isc-sac%2CROS11435', 'https://search.open.canada.ca/briefingt/record/isc-sac%2CROS12111', 'https://www.nan.ca/news/nan-congratulates-beaverhouse-first-nation-on-historic-treaty-claim/', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:beaverhouse_first_nation', 'Lovelace v. Ontario, 2000 SCC 37 ([2000] 1 SCR 950)', '2000-07-20', 'https://decisions.scc-csc.ca/scc-csc/scc-csc/en/1800/1/document.do', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:nagagamisis_first_nation', 'Nagagamisis First Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://search.open.canada.ca/briefingt/record/isc-sac%2CROS12111') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:nagagamisis_first_nation', 'CA', array['ON']::text[], 'no_band_status_seeking', '{}'::text[], null, null, null, null, 'Named in ISC briefing note ''Advancing Band Creation Negotiations with the Peskotomuhkati Nation, Skutik and Nagagamisis First Nation'' (received 2025-10-27, For Decision). Not listed in the ISC First Nation list. Self-name, location detail and website not verified from a community source.', array['https://search.open.canada.ca/briefingt/record/isc-sac%2CROS12111', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:peskotomuhkati_nation_at_skutik', 'Peskotomuhkati Nation at Skutik', 'not_federally_recognized', 'https://qonaskamkuk.com', 'Recognition research 2026-11-25', 'https://www.rcaanc-cirnac.gc.ca/eng/1100100030285/1529354158736') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:peskotomuhkati_nation_at_skutik', 'CA', array['NB']::text[], 'no_band_status_seeking', '{}'::text[], null, null, 'https://qonaskamkuk.com', 'Peskotomuhkati; Passamaquoddy (Canada)', 'Listed by CIRNAC among current negotiation/discussion tables (Atlantic). ISC briefing note (received 2025-10-27) concerns advancing band creation negotiations with the Peskotomuhkati Nation. Own site states the Peskotomuhkati are not recognized under the Indian Act in Canada and that in 2016 the federal government said it would work toward formal recognition. Not listed in the ISC First Nation list.', array['https://www.rcaanc-cirnac.gc.ca/eng/1100100030285/1529354158736', 'https://search.open.canada.ca/briefingt/record/isc-sac%2CROS12111', 'https://www.canada.ca/en/crown-indigenous-relations-northern-affairs/news/2022/09/canada-and-the-peskotomuhkati-nation-at-skutik-partner-to-launch-the-camp-chiputneticook-centre-of-excellence-project.html', 'https://qonaskamkuk.com/peskotomuhkati-nation/peskotomuhkati-persistence/', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:michel_first_nation', 'Michel First Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://docs2.cer-rec.gc.ca/ll-eng/llisapi.dll/Open/2785279') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:michel_first_nation', 'CA', array['AB']::text[], 'no_band_status_seeking', '{}'::text[], null, null, null, 'Michel Band; Michel Callihoo band; Friends of the Michel Society (representative body); Descendants of Michel First Nation Association; Michel Band Unity Group', 'Michel Band enfranchised as a band on 1958-03-31; individual members regained Indian status under Bill C-31 (1985) but band status was not restored. MFN filing on the Canada Energy Regulator record states MFN is not recognized as an Indian Act band, has had an elected Chief and Council since 1985, and filed a 2001 lawsuit to regain band status; an ISC spokesperson stated the Indian Act has no band-reinstatement provision and a new band would have to be created (APTN). Not listed in the ISC First Nation list. ICC report could not be retrieved (archive rate-limited); no own website located.', array['https://docs2.cer-rec.gc.ca/ll-eng/llisapi.dll/Open/2785279', 'https://bac-lac.wayback.archive-it.org/web/20061206232024/http://www.indianclaims.ca/pdf/FriendsoftheMichelSocietyEng.pdf', 'https://www.cbc.ca/news/indigenous/michel-first-nation-recognition-1.4234214', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:michel_first_nation', 'Indian Claims Commission inquiry, Friends of the Michel Society (report archived by Library and Archives Canada)', null, 'https://bac-lac.wayback.archive-it.org/web/20061206232024/http://www.indianclaims.ca/pdf/FriendsoftheMichelSocietyEng.pdf', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:papaschase_first_nation', 'Papaschase First Nation', 'not_federally_recognized', 'https://papaschase.ca', 'Recognition research 2026-11-25', 'https://www.scc-csc.gc.ca/cases-dossiers/search-recherche/31871') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:papaschase_first_nation', 'CA', array['AB']::text[], 'no_band_status_seeking', '{}'::text[], null, null, 'https://papaschase.ca', 'Papaschase Band; Papaschase Indian Band; Papaschase First Nation IR 136', 'SCC case summary: respondents sued as descendants of former members of the Papaschase Indian Band over the reserve surrender (1889 per SCC summary); issue of standing where the historical band ''no longer exists''; SCC restored the chambers judge''s order. Own site: band signed an adhesion to Treaty 6 in 1877 and its councillor states it seeks ''Land back and recognition''. Not listed in the ISC First Nation list.', array['https://www.scc-csc.gc.ca/cases-dossiers/search-recherche/31871', 'https://papaschase.ca', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:papaschase_first_nation', 'Canada (Attorney General) v. Lameman, 2008 SCC 14', '2008-04-03', 'https://www.scc-csc.gc.ca/cases-dossiers/search-recherche/31871', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:aseniwuche_winewak_nation', 'Aseniwuche Winewak Nation', 'not_federally_recognized', 'https://www.aseniwuche.ca', 'Recognition research 2026-11-25', 'https://www.aseniwuche.ca/the-nation/') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:aseniwuche_winewak_nation', 'CA', array['AB']::text[], 'non_status_organized', '{}'::text[], null, '1974 Land Settlement Agreements with Alberta under the Cooperative Association Act (co-operatives and enterprises near Grande Cache); lands are neither reserve nor Metis Settlement land (per AWN)', 'https://www.aseniwuche.ca', 'AWN; Aseniwuche Winewak Nation of Canada; Victor Lake, Susa Creek and Muskeg Seepee Co-operatives; Grande Cache Lake (Kamisak) and Joachim Enterprises; Wanyandie Flats', 'Formalized as a society in 1994 (per own site). Not listed in the ISC First Nation list. Provincial agreement details taken from AWN''s own site; corresponding Alberta government page not located.', array['https://www.aseniwuche.ca/the-nation/', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:kelly_lake_cree_nation', 'Kelly Lake Cree Nation', 'not_federally_recognized', 'https://www.kellylakecreenation.com', 'Recognition research 2026-11-25', 'https://www.kellylakecreenation.com/about') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:kelly_lake_cree_nation', 'CA', array['BC', 'AB']::text[], 'non_status_organized', '{}'::text[], null, null, 'https://www.kellylakecreenation.com', 'As''in''î''wa''chî Ni''yawak (Rocky Mountain People); KLCN', 'Own site: formed a legal entity under the Society Act in 1996. NRCan contribution record (2021) lists recipient legal name ''Kelly Lake Cree Nation'' (Aboriginal recipient, BC). Not listed in the ISC First Nation list. Own site makes no statement about seeking federal recognition.', array['https://www.kellylakecreenation.com/about', 'https://search.open.canada.ca/grants/record/nrcan-rncan%2C115-2021-2022-Q1-10700%2Ccurrent', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:hwlitsum_first_nation', 'Hwlitsum First Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://www.scc-csc.ca/cases-dossiers/search-recherche/38325/') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:hwlitsum_first_nation', 'CA', array['BC']::text[], 'non_status_organized', '{}'::text[], null, null, null, 'Wilson Family of Canoe Pass Band (former name, per SCC summary); Lamalcha descendants', 'SCC docket summary describes HFN as a group of Status Indians descended from the Lamalcha, formerly known as the Wilson Family of Canoe Pass Band; its 2014 representative action for Aboriginal title/rights was summarily dismissed for lack of standing (BCSC), upheld by BCCA. Not listed in the ISC First Nation list. No own website located.', array['https://www.scc-csc.ca/cases-dossiers/search-recherche/38325/', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:hwlitsum_first_nation', 'Hwlitsum First Nation v. Canada (AG), 2017 BCSC 475', '2019-03-28', 'https://www.scc-csc.ca/cases-dossiers/search-recherche/38325/', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:chacachas_treaty_nation', 'Chacachas Treaty Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://www.canada.ca/en/crown-indigenous-relations-northern-affairs/news/2024/05/chacachas-treaty-nation-and-canada-set-to-advance-reconciliation-talks.html') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:chacachas_treaty_nation', 'CA', array['SK']::text[], 'no_band_status_seeking', '{}'::text[], null, null, null, 'Chacachas First Nation; Chacachas Band', 'CIRNAC (2024-05-17): MOU for Advancing Reconciliation signed to guide discussions toward re-establishing Chacachas as a Treaty First Nation; Federal Court (2020 FC 129) found the Crown unlawfully amalgamated the historic Chacachas Band with Ochapowace (Kakisiwew) in 1884; CIRNAC states the Court found Chacachas entitled to assert Treaty 4 rights. Not listed separately in the ISC First Nation list (Ochapowace, band 363, is listed). No own website located.', array['https://www.canada.ca/en/crown-indigenous-relations-northern-affairs/news/2024/05/chacachas-treaty-nation-and-canada-set-to-advance-reconciliation-talks.html', 'https://decisions.fca-caf.ca/fc-cf/decisions/en/460388/1/document.do', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:chacachas_treaty_nation', 'Watson v. Canada', '2020-01-28', 'https://decisions.fca-caf.ca/fc-cf/decisions/en/460388/1/document.do', 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:stoney_knoll_first_nation', 'Stoney Knoll First Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://batc.ca/member_first_nations/stoney_knoll.html') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:stoney_knoll_first_nation', 'CA', array['SK']::text[], 'no_band_status_seeking', '{}'::text[], null, null, null, 'Young Chipeewayan Band; Young Chippewayan First Nation', 'Battlefords Agency Tribal Chiefs member page: Treaty 6 band (signed at Fort Carlton) no longer identified as a separate band by 1888; reserve land sold; 1982 specific claim request rejected; ICC inquiry begun 1993; claim unsettled. Lists a current chief and council. Not listed in the ISC First Nation list. No standalone own website located (tribal council page used).', array['https://batc.ca/member_first_nations/stoney_knoll.html', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.recognition_decision_document_v1 (nation_key, citation, decision_date, document_url, source_dataset) values ('ca:stoney_knoll_first_nation', 'Indian Claims Commission, The Young Chipeewayan Inquiry: Into the Claim Regarding Stoney Knoll Indian Reserve No. 107 (inquiry begun 1993 per BATC)', null, null, 'canada_unrecognized') on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:red_sky_metis_independent_nation', 'Red Sky Métis Independent Nation', 'not_federally_recognized', 'https://rsmin.ca', 'Recognition research 2026-11-25', 'https://rsmin.ca/?p=178') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:red_sky_metis_independent_nation', 'CA', array['ON']::text[], 'metis_seeking_recognition', '{}'::text[], null, null, 'https://rsmin.ca', 'RSMIN', 'Métis (tagged distinctly). Own site states a mandate to ''establish formal recognition of the RSMIN community by the Federal and Provincial Government''; located on the north shore of Lake Superior, Robinson-Superior Treaty area. No government record of recognition located.', array['https://rsmin.ca/?p=178']::text[]) on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:benoit_first_nation', 'Benoit First Nation', 'not_federally_recognized', 'https://www.benoitfirstnation.ca', 'Recognition research 2026-11-25', 'https://www.benoitfirstnation.ca/CSG_IndianBandCouncil.html') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:benoit_first_nation', 'CA', array['NL']::text[], 'non_status_organized', '{}'::text[], null, null, 'https://www.benoitfirstnation.ca', 'Penwaaq L''nu''k; Port au Port Indian Band', 'Own site: Mi''kmaq community organization formed in the 1970s with a Band Council in Cape St. George, NL. Not listed in the ISC First Nation list (Qalipu Mi''kmaq First Nation, band 34, and Miawpukek, band 47, are listed). Own site makes no statement about relationship to Qalipu or about seeking recognition. No government record located.', array['https://www.benoitfirstnation.ca/CSG_IndianBandCouncil.html', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
insert into public.native_nation_registry_v1 (nation_key, nation_name, federal_status, website_url, registry_source, registry_source_ref) values ('ca:tsetsaut_skii_km_lax_ha_nation', 'Tsetsaut / Skii km Lax Ha Nation', 'not_federally_recognized', null, 'Recognition research 2026-11-25', 'https://www2.gov.bc.ca/gov/content/environment/natural-resource-stewardship/consulting-with-first-nations/first-nations-negotiations/first-nations-a-z-listing/skii-km-lax-ha-nation-17705') on conflict (nation_key) do nothing;
insert into public.nation_recognition_record_v1 (nation_key, country, jurisdictions, federal_status_detail, ofa_petition_numbers, state_recognition, other_recognition, own_website_url, other_names, notes_factual_only, source_urls) values ('ca:tsetsaut_skii_km_lax_ha_nation', 'CA', array['BC']::text[], 'non_status_organized', '{}'::text[], null, 'Listed in BC First Nations A-Z Listing (consultation); BC records ''INAC: None''; engaged in land and resource use discussions with BC outside the BC treaty process; no completed agreements listed', null, 'Tsetsaut; Skii km Lax Ha; Tsetsaut Consultation Society', 'BC provincial listing: incorporated as the Tsetsaut Consultation Society; population approx. 30; North West region (Nass, Stikine and Skeena Rivers). Not listed in the ISC First Nation list. 2026 BCSC 1042 (as reported 2026-06-12) found BC had not met its duty to consult regarding the KSM project substantial-start determination; report states Canada does not recognize the Nation as an Indian Act band. No own website located.', array['https://www2.gov.bc.ca/gov/content/environment/natural-resource-stewardship/consulting-with-first-nations/first-nations-negotiations/first-nations-a-z-listing/skii-km-lax-ha-nation-17705', 'https://scc-csc.ca/cases-dossiers/search-recherche/41644', 'https://www.westernstandard.news/bc/bc-supreme-court-says-province-failed-to-consult-a-first-nation-not-recognized-by-ottawa-as-a-band/74146', 'https://geo.sac-isc.gc.ca/geomatics/rest/services/Donnees_Ouvertes-Open_Data/Premiere_Nation_First_Nation/MapServer/0']::text[]) on conflict do nothing;
