-- Recognition registry, v1.
--
-- Every nation in the US and Canada that is not federally recognized, from
-- official records (OFA petitioner list and decision pages, Federal Register,
-- state and provincial recognition lists, court decisions), each with its
-- own name and, where it has one, its own website. Plus the routes by which
-- nations went from unrecognized to recognized (and the acknowledgments that
-- were reversed), with the decision documents for each.
--
-- What this holds is status from official records and nothing else: no
-- description of any nation, no judgment of any community. Every row keeps
-- the URLs it came from. Nothing here is public; recognized nations appear
-- only through the comparison matrix and link to their own hubs.
--
-- Additive only. New nations are added to native_nation_registry_v1 with
-- on conflict do nothing; no existing row is changed. Data rows are
-- generated by scripts/recognition-registry-build.py from
-- data/recognition_research_20261125/ and appended below.

create table if not exists public.nation_recognition_record_v1 (
  record_id bigint generated always as identity primary key,
  nation_key text not null references public.native_nation_registry_v1 (nation_key),
  country text not null check (country in ('US', 'CA')),
  jurisdictions text[] not null default '{}',
  federal_status_detail text not null check (
    federal_status_detail in (
      'ofa_petition_active', 'ofa_letter_of_intent', 'ofa_proposed_finding_negative',
      'ofa_final_determination_negative', 'ofa_determination_reversed', 'ofa_withdrawn_or_inactive',
      'federal_terminated_not_restored', 'no_federal_petition_on_record',
      'no_band_status_seeking', 'declared_extinct', 'non_status_organized',
      'metis_seeking_recognition', 'other', 'unknown'
    )
  ),
  ofa_petition_numbers text[] not null default '{}',
  state_recognition text,
  other_recognition text,
  own_website_url text,
  other_names text,
  notes_factual_only text,
  source_urls text[] not null check (cardinality(source_urls) > 0),
  recorded_at timestamptz not null default now(),
  unique (nation_key)
);

create table if not exists public.recognition_route_v1 (
  route_id bigint generated always as identity primary key,
  nation_key text not null references public.native_nation_registry_v1 (nation_key),
  country text not null check (country in ('US', 'CA')),
  route text not null check (
    route in (
      'ofa_acknowledgment', 'congressional_recognition', 'congressional_restoration',
      'court_or_settlement', 'secretarial_reaffirmation',
      'canada_order_in_council_or_band_creation', 'other'
    )
  ),
  route_status text not null check (route_status in ('recognized', 'reversed')),
  petition_filed_date date,
  -- Most sources give only the year a petition was filed; kept at that precision.
  petition_filed_year integer check (petition_filed_year between 1800 and 2100),
  decision_date date,
  statute_citation text,
  years_to_recognition integer,
  name_in_source text not null,
  notes_factual_only text,
  source_urls text[] not null check (cardinality(source_urls) > 0),
  recorded_at timestamptz not null default now(),
  unique (nation_key, route, route_status, name_in_source)
);

create table if not exists public.recognition_decision_document_v1 (
  document_id bigint generated always as identity primary key,
  nation_key text not null references public.native_nation_registry_v1 (nation_key),
  citation text not null,
  decision_date date,
  document_url text,
  source_dataset text not null check (
    source_dataset in ('us_unrecognized', 'canada_unrecognized', 'success_routes')
  ),
  -- Filled when the document itself has been captured, not just cited.
  captured_capture_id bigint references public.native_nation_site_capture_v1 (capture_id),
  recorded_at timestamptz not null default now(),
  unique (nation_key, citation, source_dataset)
);

-- The cross-comparison grid. Unrecognized nations, and recognized nations
-- only where they have a recorded route, each linking to the nation's own hub.
create or replace view public.recognition_comparison_matrix_v1
with (security_invoker = true) as
select
  r.nation_key,
  r.nation_name,
  r.federal_status,
  r.website_url,
  coalesce(rec.country, rt.country) as country,
  rec.jurisdictions,
  rec.federal_status_detail,
  rec.ofa_petition_numbers,
  rec.state_recognition,
  rt.route,
  rt.route_status,
  rt.petition_filed_date,
  coalesce(rt.petition_filed_year, extract(year from rt.petition_filed_date)::integer) as petition_filed_year,
  rt.decision_date,
  rt.statute_citation,
  rt.years_to_recognition,
  (select count(*) from public.recognition_decision_document_v1 d where d.nation_key = r.nation_key) as decision_document_count,
  -- Each nation's own hub (its council-approved page set). Only the three
  -- Recognition Atlas pages exist today, under their short ids; every other
  -- nation's hub is built in a later, separately approved step, so it is null.
  case when r.nation_key like 'self:%'
       then '/recognition-atlas/' || substr(r.nation_key, 6) end as hub_path
from public.native_nation_registry_v1 r
left join public.nation_recognition_record_v1 rec on rec.nation_key = r.nation_key
left join public.recognition_route_v1 rt on rt.nation_key = r.nation_key
where rec.nation_key is not null or rt.nation_key is not null;

alter table public.nation_recognition_record_v1 enable row level security;
alter table public.recognition_route_v1 enable row level security;
alter table public.recognition_decision_document_v1 enable row level security;
revoke all on public.nation_recognition_record_v1 from public, anon, authenticated;
revoke all on public.recognition_route_v1 from public, anon, authenticated;
revoke all on public.recognition_decision_document_v1 from public, anon, authenticated;
revoke all on public.recognition_comparison_matrix_v1 from public, anon, authenticated;
grant select, insert on public.nation_recognition_record_v1 to service_role;
grant select, insert on public.recognition_route_v1 to service_role;
grant select, insert, update on public.recognition_decision_document_v1 to service_role;
grant select on public.recognition_comparison_matrix_v1 to service_role;

-- Data (generated; see header).
